function healthMap(){const m={};for(const h of snap.health||[])m[h.deployment]=h;return m}
function render(){const h=healthMap(),ds=snap.deployments||[];const sl=$('#routerStrategyLabel');if(sl)sl.textContent=snap.config?.routing?.strategy||'ready_mesh';$('#sDeploy').textContent=snap.deployment_total??ds.length;let ok=Number(snap.health_counts?.healthy??0),cd=Number(snap.health_counts?.cooldown??0),ls=[];for(const d of ds){const x=h[d.id]||{};if(!snap.health_counts&&x.status==='healthy')ok++;if(!snap.health_counts&&x.status==='cooldown')cd++;if(x.ewma_latency_ms)ls.push(x.ewma_latency_ms)}$('#sHealthy').textContent=ok;$('#sCooldown').textContent=cd;$('#sLatency').textContent=ls.length?Math.round(ls.reduce((a,b)=>a+b,0)/ls.length)+' ms':'—';renderRing(ds,h);renderProviders(h);renderModels(ds,h);renderEvents();$('#settingsJson').textContent=JSON.stringify(snap.config||{},null,2)}
function renderRing(ds,h){const ring=$('#ring');[...ring.querySelectorAll('.node')].forEach(x=>x.remove());const svg=$('#links');svg.innerHTML='';const shown=ds.slice(0,100),W=ring.clientWidth,H=ring.clientHeight,cx=W/2,cy=H/2;ring.classList.toggle('dense',shown.length>24);const ringCount=Math.max(1,Math.min(4,Math.ceil(shown.length/25)));shown.forEach((d,i)=>{const ri=Math.floor(i/25),start=ri*25,count=Math.min(25,shown.length-start),pos=i-start,a=Math.PI*2*pos/Math.max(count,1)-Math.PI/2;const frac=ringCount===1?1:(ri+1)/ringCount;const rx=shown.length>24?110+frac*Math.min(W*.34,300):Math.min(W*.38,360),ry=shown.length>24?60+frac*Math.min(H*.31,210):Math.min(H*.36,190),x=cx+Math.cos(a)*rx,y=cy+Math.sin(a)*ry,st=(h[d.id]||{}).status||'unknown';const n=document.createElement('div');n.className='node '+st;n.style.left=x+'px';n.style.top=y+'px';n.title=`${d.model} • ${d.provider_name||d.provider_id} • ${st}`;n.innerHTML=`<strong>${esc(d.model)}</strong><small>${esc(d.provider_name||d.provider_id)}</small><span class="badge">${esc(st)}</span>`;ring.appendChild(n);const l=document.createElementNS('http://www.w3.org/2000/svg','line');for(const [k,v] of Object.entries({x1:cx,y1:cy,x2:x,y2:y,stroke:st==='healthy'?'#214d42':st==='cooldown'?'#512832':st==='degraded'?'#665126':'#26384f','stroke-width':1,'stroke-dasharray':'3 5'}))l.setAttribute(k,v);svg.appendChild(l)});if(ds.length>100){const n=document.createElement('div');n.className='node degraded';n.style.left=cx+'px';n.style.top=(H-28)+'px';n.innerHTML=`<strong>+${ds.length-100} more</strong><small>See Models table</small>`;ring.appendChild(n)}}
function renderProviders(h){$('#providerGrid').innerHTML=providerSummaries.map(p=>{const ds=(snap.deployments||[]).filter(d=>d.provider_id===p.id),ok=ds.filter(d=>(h[d.id]||{}).status==='healthy').length;return `<article class="provider-card"><div class="provider-card-top"><div class="provider-mark">${esc((p.name||p.id).slice(0,1).toUpperCase())}</div><div class="provider-copy"><h3>${esc(p.name||p.id)}</h3><p>${esc(p.type)} · ${p.model_count} models</p></div><span class="pill ${p.enabled?'on':'off'}">${p.enabled?'Enabled':'Disabled'}</span></div><div class="provider-url">${esc(p.base_url)}</div><div class="provider-meta"><span>${p.has_secret?`${p.credential_count||1} credential(s)`:'No credential'}</span><span>${ok}/${ds.length} healthy</span></div><button class="edit-provider btn secondary" data-id="${esc(p.id)}">Edit provider</button></article>`}).join('')||'<div class="empty-state"><strong>No providers yet.</strong><span>Add an OpenAI-compatible or Anthropic-compatible upstream.</span></div>';$$('.edit-provider').forEach(b=>b.onclick=()=>openEdit(b.dataset.id))}
function renderModels(ds,h){$('#modelRows').innerHTML=ds.map(d=>{const x=h[d.id]||{status:'unknown'};return `<tr><td>${esc(d.id)}</td><td>${esc(d.provider_id)}</td><td>${esc(d.model)}</td><td><span class="status ${esc(x.status)}">${esc(x.status)}</span></td><td>${x.ewma_latency_ms?Math.round(x.ewma_latency_ms)+' ms':'—'}</td><td>${x.consecutive_failures||0}</td><td><button class="btn secondary row-act" data-act="test" data-provider="${esc(d.provider_id)}" data-model="${esc(d.model)}">Test</button></td><td><button class="btn danger-ghost row-act" data-act="disable" data-provider="${esc(d.provider_id)}" data-mid="${esc(d.id.slice(d.provider_id.length+1))}" data-model="${esc(d.model)}">Disable</button></td></tr>`}).join('')||'<tr><td colspan="8" style="color:var(--muted)">No deployments yet.</td></tr>';$$('.row-act').forEach(b=>b.onclick=()=>{if(b.dataset.act==='test')testSavedModel(b.dataset.provider,[b.dataset.model],b);else toggleSavedModel(b.dataset.provider,b.dataset.mid,false,b)})}
async function testSavedModel(providerID,models,btn){const old=btn.textContent;btn.disabled=true;btn.textContent='…';try{const d=await api('/admin/api/provider-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:providerID,test_models:models})});const r=(d.results||[])[0]||{};toast(`${models.join(', ')}: ${r.ok?'PASS':'FAIL'} · ${r.status_code||'—'} · ${r.latency_ms??'—'} ms${r.error?' · '+r.error:''}`,!r.ok)}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent=old}}
