function slug(s){return s.toLowerCase().trim().replace(/[^a-z0-9._-]+/g,'-').replace(/^-+|-+$/g,'')||'model'}
function defaultModelMeta(m,i=0){return{id:slug(m),model:m,aliases:$('#pAliases').value.split(',').map(x=>x.trim()).filter(Boolean),enabled:true,priority:i,weight:1,capabilities:{streaming:$('#pCapStreaming').checked,tools:$('#pCapTools').checked,vision:$('#pCapVision').checked,reasoning:$('#pCapReasoning').checked}}}
function ensureModelMeta(m,i=0){if(!editor.modelMeta.has(m))editor.modelMeta.set(m,defaultModelMeta(m,i));const x=editor.modelMeta.get(m);x.capabilities=x.capabilities||{streaming:true,tools:true,vision:false,reasoning:false};if(!Array.isArray(x.aliases))x.aliases=[];if(!Number.isFinite(x.priority))x.priority=i;if(!Number.isFinite(x.weight)||x.weight<=0)x.weight=1;return x}
function readForm(){let hs={};const raw=$('#pHeaders').value.trim();if(raw){try{hs=JSON.parse(raw)}catch{throw new Error('Extra headers must be valid JSON')}}let creds=[];const cr=$('#pCredentials').value.trim();if(cr){try{creds=JSON.parse(cr);if(!Array.isArray(creds))throw new Error()}catch{throw new Error('Credential pool must be a JSON array')}}const models=[...editor.selected].map((m,i)=>{const x=ensureModelMeta(m,i),c=x.capabilities||{};return{id:x.id||slug(m),model:m,aliases:[...new Set((x.aliases||[]).map(v=>String(v).trim()).filter(Boolean))],enabled:x.enabled!==false,priority:Number.isFinite(Number(x.priority))?Number(x.priority):i,weight:Number(x.weight)>0?Number(x.weight):1,capabilities:{streaming:c.streaming!==false,tools:c.tools!==false,vision:!!c.vision,reasoning:!!c.reasoning}}});const p={id:$('#pId').value.trim(),name:$('#pName').value.trim(),type:$('#pType').value,base_url:$('#pBase').value.trim(),api_key:$('#pKey').value,api_key_env:$('#pKeyEnv').value.trim(),credentials:creds,auth_mode:$('#pAuth').value,headers:hs,forward_headers:(()=>{const v=$('#pForwardHeaders').value.split(',').map(x=>x.trim()).filter(Boolean);if(v.length)return v;if(editor.mode==='add')return null;if(editor.forwardHeadersTouched)return[];return editor.originalForwardHeaders===undefined?null:editor.originalForwardHeaders})(),proxy_url:$('#pProxy').value.trim(),chat_path:$('#pChatPath').value.trim(),messages_path:$('#pMessagesPath').value.trim(),models_path:$('#pModelsPath').value.trim(),count_tokens_path:$('#pCountPath').value.trim(),max_concurrency:Math.max(1,parseInt($('#pConcurrency').value||'32',10)),stream_idle_timeout_seconds:Math.max(10,parseInt($('#pStreamIdle').value||'180',10)),enabled:$('#pEnabled').checked,models};if(!p.id)throw new Error('Internal ID is required');if(!p.name)p.name=p.id;if(!p.base_url)throw new Error('Base URL is required');return p}
function payload(p){return{provider:p,preserve_secret:editor.mode==='edit'&&!editor.secretDirty,test_models:[...editor.selected]}}
function renderPicker(){const all=[...new Set([...editor.detected,...editor.selected])];for(const [i,m] of all.entries())ensureModelMeta(m,i);const sel=[...editor.selected],dis=sel.filter(m=>(editor.modelMeta.get(m)||{enabled:true}).enabled===false).length;$('#pickerSummary').textContent=all.length?`${sel.length} of ${all.length} selected · ${dis} disabled`:'No models yet — detect or add manually.';$('#modelPicker').innerHTML=all.length?all.map((m,i)=>{const x=ensureModelMeta(m,i),c=x.capabilities||{};return `<div class="model-option ${x.enabled===false?'off':''}"><div class="model-option-head"><input class="model-select" type="checkbox" data-model="${esc(m)}" ${editor.selected.has(m)?'checked':''}><strong>${esc(m)}</strong><span class="spacer"></span><label class="model-onoff" title="Active in routing (kept in config when off)"><input data-model="${esc(m)}" data-enabled type="checkbox" ${x.enabled!==false?'checked':''}>On</label><button class="btn secondary model-test-btn" data-testmodel type="button">Test</button></div><div class="model-meta-grid"><label>Aliases<input data-model="${esc(m)}" data-meta="aliases" value="${esc((x.aliases||[]).join(', '))}" placeholder="coding, auto"></label><label>Priority<input data-model="${esc(m)}" data-meta="priority" type="number" value="${Number.isFinite(Number(x.priority))?Number(x.priority):i}"></label><label>Weight<input data-model="${esc(m)}" data-meta="weight" type="number" min="0.01" step="0.1" value="${Number(x.weight)>0?Number(x.weight):1}"></label></div><div class="model-cap-row"><label><input data-model="${esc(m)}" data-cap="streaming" type="checkbox" ${c.streaming!==false?'checked':''}>Streaming</label><label><input data-model="${esc(m)}" data-cap="tools" type="checkbox" ${c.tools!==false?'checked':''}>Tools</label><label><input data-model="${esc(m)}" data-cap="vision" type="checkbox" ${c.vision?'checked':''}>Vision</label><label><input data-model="${esc(m)}" data-cap="reasoning" type="checkbox" ${c.reasoning?'checked':''}>Reasoning</label></div><div class="model-test-out" data-testout></div></div>`}).join(''):'<div class="model-empty">No models selected yet.</div>';$$('#modelPicker .model-select').forEach(x=>x.onchange=()=>{x.checked?editor.selected.add(x.dataset.model):editor.selected.delete(x.dataset.model);renderPicker()});$$('#modelPicker [data-meta]').forEach(x=>x.oninput=()=>{const m=x.dataset.model,meta=ensureModelMeta(m);if(x.dataset.meta==='aliases')meta.aliases=x.value.split(',').map(v=>v.trim()).filter(Boolean);else if(x.dataset.meta==='priority')meta.priority=parseInt(x.value||'0',10);else if(x.dataset.meta==='weight')meta.weight=Math.max(.01,parseFloat(x.value||'1'))});$$('#modelPicker [data-cap]').forEach(x=>x.onchange=()=>{const meta=ensureModelMeta(x.dataset.model);meta.capabilities=meta.capabilities||{};meta.capabilities[x.dataset.cap]=x.checked});$$('#modelPicker [data-enabled]').forEach(x=>x.onchange=()=>{const meta=ensureModelMeta(x.dataset.model);meta.enabled=x.checked;renderPicker()});$$('#modelPicker .model-option').forEach(card=>{const cb=card.querySelector('.model-select');if(!cb)return;const m=cb.dataset.model,btn=card.querySelector('[data-testmodel]'),out=card.querySelector('[data-testout]');if(btn)btn.onclick=async()=>{btn.disabled=true;out.className='model-test-out';out.textContent='Testing…';try{const body={provider:readForm(),preserve_secret:editor.mode==='edit'&&!editor.secretDirty,test_models:[m]};const d=await api('/admin/api/provider-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const r=(d.results||[])[0]||{};out.className='model-test-out '+(r.ok?'ok':'fail');out.textContent=`${r.ok?'PASS':'FAIL'} · ${r.status_code||'—'} · ${r.latency_ms??'—'} ms${r.error?' · '+r.error:''}`}catch(e){out.className='model-test-out fail';out.textContent=e.message}finally{btn.disabled=false}}})}
$('#addModelBtn').onclick=()=>{const m=$('#manualModel').value.trim();if(!m)return;editor.detected=[...new Set([...editor.detected,m])];editor.selected.add(m);ensureModelMeta(m,editor.detected.length-1);$('#manualModel').value='';renderPicker()};$('#manualModel').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#addModelBtn').click()}};
