$('#testProviderBtn').onclick=async()=>{try{const p=readForm();if(!editor.selected.size)throw new Error('Select at least one model');$('#testProviderBtn').disabled=true;$('#testResults').innerHTML='<div class="inline-status">Testing…</div>';const d=await api('/admin/api/provider-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload(p))});$('#testResults').innerHTML=(d.results||[]).map(x=>`<div class="test-row ${x.ok?'ok':'fail'}"><strong>${esc(x.model)}</strong><span>${x.ok?'PASS':'FAIL'}</span><span>${x.status_code||'—'}</span><span>${x.latency_ms} ms</span><small>${esc(x.error||'')}</small></div>`).join('');toast(d.ok?'All selected models passed':`${d.passed}/${d.total} models passed`,!d.ok)}catch(e){$('#testResults').innerHTML=`<div class="inline-status badtext">${esc(e.message)}</div>`;toast(e.message,true)}finally{$('#testProviderBtn').disabled=false}};
$('#saveProviderBtn').onclick=async()=>{try{const p=readForm(),b=JSON.stringify(payload(p));$('#saveProviderBtn').disabled=true;if(editor.mode==='add')await api('/admin/api/providers',{method:'POST',headers:{'Content-Type':'application/json'},body:b});else await api('/admin/api/providers/'+encodeURIComponent(editor.originalId),{method:'PUT',headers:{'Content-Type':'application/json'},body:b});toast('Provider saved and runtime reloaded');modal(false);await refresh()}catch(e){toast(e.message,true)}finally{$('#saveProviderBtn').disabled=false}};
