async function loadKeys(){try{keyState=await api('/admin/api/client-keys')}catch{}}
async function renderKeys(){await loadKeys();$('#keyReqState').textContent=keyState.required?'REQUIRED':'OPEN';$('#keyReqState').style.color=keyState.required?'var(--warn)':'var(--muted)';$('#ckRequired').checked=!!keyState.required;$('#keyRows').innerHTML=(keyState.keys||[]).map(k=>`<tr><td>${esc(k.name||k.id)}</td><td><code class="keyval" data-key="${esc(k.key)}">${esc(k.key.slice(0,7))}…${esc(k.key.slice(-4))}</code> <button class="icon-btn reveal-key" data-id="${esc(k.id)}">Show</button> <button class="icon-btn copy-key" data-id="${esc(k.id)}">Copy</button></td><td><label class="model-onoff"><input data-keytoggle="${esc(k.id)}" type="checkbox" ${k.enabled?'checked':''}>On</label></td><td>${k.requests||0}</td><td><button class="btn danger-ghost row-act" data-keydel="${esc(k.id)}">Delete</button></td></tr>`).join('')||'<tr><td colspan="5" style="color:var(--muted)">No keys yet.</td></tr>';$$('#keyRows [data-keytoggle]').forEach(x=>x.onchange=async()=>{try{await api('/admin/api/client-keys/'+x.dataset.keytoggle,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:x.checked})});toast('Key updated');await renderKeys()}catch(e){toast(e.message,true);await renderKeys()}});$$('#keyRows [data-keydel]').forEach(x=>x.onclick=async()=>{if(!confirm('Delete this access key? Clients using it stop working immediately.'))return;try{await api('/admin/api/client-keys/'+x.dataset.keydel,{method:'DELETE'});toast('Key deleted');await renderKeys()}catch(e){toast(e.message,true)}});$$('#keyRows .reveal-key').forEach(x=>x.onclick=()=>{const k=keyState.keys.find(y=>y.id===x.dataset.id),el=x.parentElement.querySelector('.keyval');if(el.textContent===k.key){el.textContent=k.key.slice(0,7)+'…'+k.key.slice(-4);x.textContent='Show'}else{el.textContent=k.key;x.textContent='Hide'}});$$('#keyRows .copy-key').forEach(x=>x.onclick=async()=>{const k=keyState.keys.find(y=>y.id===x.dataset.id);try{await navigator.clipboard.writeText(k.key);toast('Key copied to clipboard')}catch{window.prompt('Copy the key:',k.key)}})}
$('#ckRequired').onchange=async()=>{try{await api('/admin/api/client-auth-required',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({required:$('#ckRequired').checked})});toast($('#ckRequired').checked?'Client keys now required on /v1/*':'Client auth disabled — /v1/* is open');await renderKeys()}catch(e){toast(e.message,true);$('#ckRequired').checked=!$('#ckRequired').checked}};
$('#createKeyBtn').onclick=async()=>{try{const d=await api('/admin/api/client-keys',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('#newKeyName').value.trim()})});$('#newKeyName').value='';toast('Key generated — copy it now: '+d.key.key);try{await navigator.clipboard.writeText(d.key.key)}catch{};await renderKeys();const el=document.querySelector(`[data-key="${d.key.key}"]`);if(el)el.textContent=d.key.key}catch(e){toast(e.message,true)}};
function fmtCost(n){return '$'+(Number(n)||0).toFixed(4).replace(/0+$/,'').replace(/\.$/,'')}
function renderUsage(){const u=usageState||{totals:{},by_provider:{},by_key:{}};$('#uRequests').textContent=u.totals?.requests||0;$('#uInTok').textContent=(u.totals?.input_tokens||0).toLocaleString();$('#uOutTok').textContent=(u.totals?.output_tokens||0).toLocaleString();$('#uCost').textContent=fmtCost(u.totals?.est_cost_usd);const row=(k,v)=>`<tr><td>${esc(k)}</td><td>${v.requests||0}</td><td>${(v.input_tokens||0).toLocaleString()}</td><td>${(v.output_tokens||0).toLocaleString()}</td><td>${fmtCost(v.est_cost_usd)}</td></tr>`;$('#usageProviderRows').innerHTML=Object.entries(u.by_provider||{}).sort((a,b)=>b[1].requests-a[1].requests).map(([k,v])=>row(k,v)).join('')||'<tr><td colspan="5" style="color:var(--muted)">No usage yet.</td></tr>';$('#usageKeyRows').innerHTML=Object.entries(u.by_key||{}).sort((a,b)=>b[1].requests-a[1].requests).map(([k,v])=>row(k,v)).join('')||'<tr><td colspan="5" style="color:var(--muted)">No usage yet.</td></tr>';renderRecent()}
async function loadUsage(){try{usageState=await api('/admin/api/usage');if($('#usage').classList.contains('active'))renderUsage()}catch{}}
async function loadRecent(){try{recentState=await api('/admin/api/requests?limit=100');if($('#usage').classList.contains('active'))renderUsage()}catch{}}
function renderRecent(){const rs=(recentState&&recentState.requests)||[];$('#recentReqRows').innerHTML=rs.slice(0,100).map(q=>`<tr><td>${new Date(q.time).toLocaleTimeString()}</td><td>${esc(q.key_name||'—')}</td><td>${esc(q.deployment||'—')}${q.provider_name?` <small style="color:var(--muted)">${esc(q.provider_name)}</small>`:''}</td><td>${esc(q.model||'—')}${q.stream?' <small style="color:var(--cyan)">SSE</small>':''}</td><td><span class="status ${q.status<400?'healthy':q.status<500?'degraded':'cooldown'}">${q.status}</span></td><td>${q.latency_ms} ms</td><td>${(q.input_tokens||0).toLocaleString()} / ${(q.output_tokens||0).toLocaleString()}</td><td>${fmtCost(q.est_cost_usd)}</td></tr>`).join('')||'<tr><td colspan="8" style="color:var(--muted)">No data-plane requests yet.</td></tr>'}
$('#usageResetBtn').onclick=async()=>{try{await api('/admin/api/usage/reset',{method:'POST'});toast('Usage counters reset');await loadUsage();renderUsage()}catch(e){toast(e.message,true)}};

function renderResolvedCreds(reveal){const list=editor.resolvedCreds||[];const box=$('#resolvedCreds');if(!box)return;box.innerHTML=list.length?list.map((c,i)=>`<div class="cred-row"><strong>${esc(c.name)}</strong><span class="cred-src">${esc(c.source)}</span><code class="keyval" data-cred="${i}">${reveal?esc(c.key):esc(maskCred(c.key))}</code><button class="icon-btn cred-toggle" data-i="${i}">${reveal?'Hide':'Show'}</button><button class="icon-btn cred-copy" data-i="${i}">Copy</button></div>`).join(''):'<p class="hint">No credentials configured (auth_mode none).</p>';$$('.cred-toggle').forEach(x=>x.onclick=()=>{const i=+x.dataset.i,el=box.querySelector(`[data-cred="${i}"]`),showing=el.textContent===editor.resolvedCreds[i].key;el.textContent=showing?maskCred(editor.resolvedCreds[i].key):editor.resolvedCreds[i].key;x.textContent=showing?'Show':'Hide'});$$('.cred-copy').forEach(x=>x.onclick=async()=>{const k=editor.resolvedCreds[+x.dataset.i].key;try{await navigator.clipboard.writeText(k);toast('Credential copied')}catch{window.prompt('Copy the key:',k)}})}
function maskCred(k){k=String(k||'');return k.length<=10?k.slice(0,2)+'…':k.slice(0,6)+'…'+k.slice(-4)}
$('#revealAllCreds')&&($('#revealAllCreds').onclick=()=>{const anyShown=!!$('.cred-toggle')&&Array.from($$('.cred-toggle')).some(x=>x.textContent==='Hide');renderResolvedCreds(anyShown);$('#revealAllCreds').textContent=anyShown?'Hide keys':'Show keys'});

$('#previewBtn')&&($('#previewBtn').onclick=async()=>{const m=$('#previewModel').value.trim();if(!m){toast('Enter a model or alias to preview',true);return}const btn=$('#previewBtn');btn.disabled=true;try{const body={model:m,session_key:$('#previewSession').checked?('preview-'+Math.floor(Date.now()/1000)):''};const d=await api('/admin/api/route-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const out=$('#previewOut');out.style.display='block';const cs=d.candidates||[];out.innerHTML=`<div class="preview-head"><strong>Route Preview: ${esc(d.model)}</strong><span class="hint">strategy ${esc(d.strategy)} · ${d.candidate_count} eligible candidate(s) · max attempts ${d.max_attempts} · fallback ${d.fallback_enabled?'on':'off'}${d.session_pinned?` · pinned: ${esc(d.session_pinned)}`:''}</span></div>${(d.notes||[]).map(n=>`<p class="hint" style="color:var(--warn);margin:6px 0">${esc(n)}</p>`).join('')}<div class="preview-list">${cs.map((c,i)=>`<div class="preview-card ${i===0?'top':''}"><div class="preview-top"><span class="rank">#${i+1}</span><strong>${esc(c.deployment_id)}</strong><span class="status ${esc(c.health)}">${esc(c.health)}</span>${c.session_pinned?'<span class="live">PIN</span>':''}<span class="spacer"></span><span class="hint">score ${c.score} · tier ${c.priority} · w ${c.weight} · ${c.ewma_latency_ms} ms · pressure ${(c.capacity_pressure*100).toFixed(0)}%</span></div>${c.reasons?`<ul class="preview-reasons">${c.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>`:''}</div>`).join('')||'<p class="hint">No eligible deployments.</p>'}</div>`}catch(e){toast(e.message,true)}finally{btn.disabled=false}});

/* ================= POWER UI upgrade =================
   Dashboard ideas adopted from one-api/new-api, LiteLLM, Helicone, Portkey
   and claude-code-router: live traffic deltas, filterable event stream,
   filterable request explorer, per-deployment proof age, one-click E2E
   route test, per-provider batch tests, generated CLI snippets. */
const PW={paused:false,series:[],lastUsage:null,lastFail:null,lastT:0,win:300,evFilter:'all',evQuery:'',evPaused:false,reqFilter:{status:'all',q:'',sse:false},reqOpen:null,modelFilter:{q:'',status:'all',sort:'id',dir:1}};
function agoStr(v){const t=Date.parse(v);if(!t)return'never';const s=Math.max(0,Math.round((Date.now()-t)/1000));if(s<60)return s+'s ago';if(s<3600)return Math.floor(s/60)+'m ago';if(s<86400)return Math.floor(s/3600)+'h'+Math.floor(s%3600/60)+'m ago';return Math.floor(s/86400)+'d ago'}
function fmtInt(n){return (Number(n)||0).toLocaleString()}
function evClass(k){k=k||'';if(k==='route_ok'||k==='probe_ready'||k==='recovery_ready')return'ok';if(k==='guardrail_blocked'||k==='client_auth_rejected')return'guardrail';if(k==='route_fail'||k==='route_timeout'||k==='stream_fail'||k==='probe_fail'||k==='recovery_fail'||k==='internal_panic'||k==='gateway_overloaded'||k==='client_disconnect')return'bad';if(k==='failover'||k==='probe_quarantine'||k==='recovery_cooldown'||k==='recovery_deferred'||k==='recovery_wait'||k==='recovery_queue_full')return'warn';return'info'}
function evMatch(k,f){k=k||'';const c=evClass(k);if(f==='all')return true;if(f==='ok')return c==='ok';if(f==='bad')return c==='bad';if(f==='guardrail')return c==='guardrail';if(f==='warn')return c==='warn';if(f==='probe')return k.indexOf('probe_')===0;return true}

/* --- live series capture: poll deltas from cumulative counters --- */
const _pwLoadUsage=loadUsage;
loadUsage=async function(){const prevU=PW.lastUsage,prevF=PW.lastFail,t0=PW.lastT||Date.now();await _pwLoadUsage();PW.lastT=Date.now();const tot=usageState&&usageState.totals;if(tot){if(prevU){const dt=Math.max(1,(PW.lastT-t0)/1000);const rpm=Math.max(0,(tot.requests-prevU.requests)/dt*60);let epm=0;if(prevF!=null){let f=0;const hh=healthMap();for(const k in hh)f+=hh[k].failures||0;epm=Math.max(0,(f-prevF)/dt*60)}PW.series.push({t:PW.lastT,rpm,epm});if(PW.series.length>240)PW.series=PW.series.slice(-240)}PW.lastUsage=tot}let fsum=0;const hh=healthMap();for(const k in hh)fsum+=hh[k].failures||0;PW.lastFail=fsum};

/* --- wrapped render: refresh every power widget after the base render --- */
const _pwRender=render;
render=function(){_pwRender();renderTrafficKPIs();renderTrafficChart();renderTopDeployments();renderActivityStrip()};

function renderTrafficKPIs(){let s=0,f=0;const hh=snap.health||[];for(const x of hh){s+=x.successes||0;f+=x.failures||0}const t=s+f;const el=$('#kSuccess');if(el)el.textContent=t?((s/t*100).toFixed(1)+'%'):'—';const u=usageState&&usageState.totals;if(u){const kt=$('#kTokens');if(kt){kt.textContent=fmtInt(u.input_tokens)+' / '+fmtInt(u.output_tokens)}const kc=$('#kCost');if(kc)kc.textContent=fmtCost(u.est_cost_usd)}const last=PW.series[PW.series.length-1];if(last){const kr=$('#kRpm');if(kr)kr.textContent=last.rpm<10?last.rpm.toFixed(1):Math.round(last.rpm);const ke=$('#kEpm');if(ke)ke.textContent=last.epm<10?last.epm.toFixed(1):Math.round(last.epm)}}

function renderTrafficChart(){const box=$('#trafficChart');if(!box)return;const now=Date.now();const pts=PW.series.filter(p=>now-p.t<=PW.win*1000);const W=box.clientWidth||900,H=180,n=pts.length;if(n<2){box.innerHTML='<p class="hint" style="padding:24px;color:var(--muted)">Collecting live samples… keep this page open; each poll adds a point.</p>';const cp=$('#chartPeak');if(cp)cp.textContent='';return}
const maxR=Math.max(1,...pts.map(p=>p.rpm)),maxE=Math.max(1,...pts.map(p=>p.epm));const maxV=maxR;const t0=pts[0].t,t1=pts[n-1].t,span=Math.max(1,t1-t0);const X=t=>((t-t0)/span*(W-8)+4).toFixed(1);const Y=v=>(H-14-v/maxV*(H-34)).toFixed(1);
let area='M '+X(pts[0].t)+' '+Y(0),line='';pts.forEach(p=>{line+=(line?' L ':'M ')+X(p.t)+' '+Y(p.rpm);});area+=line.replace(/^M /,' L ')+' L '+X(t1)+' '+Y(0)+' Z';
let eline='';pts.forEach(p=>{eline+=(eline?' L ':'M ')+X(p.t)+' '+Y(Math.min(p.epm,maxV))});
let grid='';for(let i=1;i<=3;i++){const gy=(H-14)-i*(H-34)/4;grid+=`<line x1="4" y1="${gy}" x2="${W-4}" y2="${gy}" stroke="#1b2a3d" stroke-width="1"></line><text x="8" y="${gy-3}" fill="#4d6076" font-size="9">${(maxV*i/4).toFixed(maxV<10?1:0)}</text>`}
box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" width="100%" height="${H}">${grid}<path d="${area}" fill="rgba(47,111,86,.25)" stroke="none"></path><path d="${line}" fill="none" stroke="#39a97c" stroke-width="1.6"></path><path d="${eline}" fill="none" stroke="#c0504f" stroke-width="1.3" stroke-dasharray="4 3"></path></svg>`;
const peak=Math.max(...pts.map(p=>p.rpm));const cp=$('#chartPeak');if(cp)cp.textContent=`peak ${peak<10?peak.toFixed(1):Math.round(peak)} req/min · ${n} samples`}

function renderTopDeployments(){const el=$('#topDeployments');if(!el)return;const u=usageState||{};const rows=Object.entries(u.by_provider||{}).sort((a,b)=>b[1].requests-a[1].requests).slice(0,6);const max=Math.max(1,...rows.map(r=>r[1].requests));el.innerHTML=rows.map(([k,v])=>`<div class="top-row"><div class="top-line"><strong>${esc(k)}</strong><span>${fmtInt(v.requests)} req · ${fmtCost(v.est_cost_usd)}</span></div><div class="top-bar"><i style="width:${(v.requests/max*100).toFixed(1)}%"></i></div></div>`).join('')||'<p class="hint" style="color:var(--muted)">No routed requests yet.</p>'}

function renderActivityStrip(){const el=$('#activityStrip');if(!el)return;const es=(snap.events||[]).slice().reverse().slice(0,8);el.innerHTML=es.map(e=>{const c=evClass(e.kind);return `<div class="event ev-${c}"><time>${new Date(e.time).toLocaleTimeString()}</time><span class="kind">${esc(e.kind)}</span><span class="evmsg">${esc((e.deployment||'')+' '+(e.message||'')).slice(0,120)}</span></div>`}).join('')||'<p class="hint" style="color:var(--muted)">No events yet.</p>'}

/* --- Events tab: chips + search + pause --- */
renderEvents=function(){const list=$('#eventList');if(!list)return;if(PW.evPaused)return;const all=(snap.events||[]).slice().reverse();const q=PW.evQuery.toLowerCase();const rows=all.filter(e=>evMatch(e.kind,PW.evFilter)&&(!q||((e.kind||'')+' '+(e.deployment||'')+' '+(e.message||'')+' '+(e.error_type||'')).toLowerCase().includes(q)));const cnt=$('#evCount');if(cnt)cnt.textContent=rows.length+' / '+all.length;list.innerHTML=rows.slice(0,150).map(e=>{const c=evClass(e.kind);return `<div class="event ev-${c}"><time>${new Date(e.time).toLocaleTimeString()}</time><span class="kind">${esc(e.kind)}</span><span class="evmsg">${esc((e.deployment||'')+' '+(e.message||''))}</span><span class="hint">${esc(e.error_type||'')}</span><span>${e.latency_ms?e.latency_ms+' ms':''}</span></div>`}).join('')||'<p>No matching events.</p>'};
$$('#evChips .chip').forEach(b=>b.onclick=()=>{$$('#evChips .chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');PW.evFilter=b.dataset.evf;renderEvents()});
$('#evQuery').addEventListener('input',()=>{PW.evQuery=$('#evQuery').value.trim();renderEvents()});
$('#evPauseBtn').onclick=()=>{PW.evPaused=!PW.evPaused;$('#evPauseBtn').textContent=PW.evPaused?'▶ Resume':'⏸ Pause';if(!PW.evPaused)renderEvents()};

/* --- Requests explorer: status/SSE/search filters + expandable rows --- */
renderRecent=function(){const rs=(recentState&&recentState.requests)||[];const f=PW.reqFilter;const q=(f.q||'').toLowerCase();const rows=rs.filter(r=>{if(f.status==='2xx'&&!(r.status>=200&&r.status<300))return false;if(f.status==='4xx'&&!(r.status>=400&&r.status<500))return false;if(f.status==='5xx'&&!(r.status>=500))return false;if(f.sse&&!r.stream)return false;if(q){const hay=((r.key_name||'')+' '+(r.deployment||'')+' '+(r.provider_name||'')+' '+(r.model||'')+' '+(r.path||'')+' '+(r.error||'')).toLowerCase();if(!hay.includes(q))return false}return true});
const cnt=$('#reqCount');if(cnt)cnt.textContent=rows.length+' of '+rs.length+' recent requests shown';$('#recentReqRows').innerHTML=rows.slice(0,150).map(r=>{const open=PW.reqOpen===r.request_id;const cls=r.status<300?'healthy':r.status<500?'degraded':'cooldown';const main=`<tr class="req-row ${open?'open':''}" data-rid="${esc(r.request_id||'')}"><td>${new Date(r.time).toLocaleTimeString()}</td><td>${esc(r.key_name||'—')}</td><td>${esc(r.deployment||'—')}${r.provider_name?` <small style="color:var(--muted)">${esc(r.provider_name)}</small>`:''}</td><td>${esc(r.model||'—')}${r.stream?' <small style="color:var(--cyan)">SSE</small>':''}</td><td><span class="status ${cls}">${r.status}</span></td><td>${r.latency_ms} ms</td><td>${fmtInt(r.input_tokens)} / ${fmtInt(r.output_tokens)}</td><td>${fmtCost(r.est_cost_usd)}</td></tr>`;const det=open?`<tr class="req-detail"><td colspan="8"><code>${esc(r.request_id||'')}</code> · <code>${esc(r.path||'')}</code>${r.error?` · <span style="color:var(--bad)">${esc(r.error)}</span>`:''}</td></tr>`:'';return main+det}).join('')||'<tr><td colspan="8" style="color:var(--muted)">No requests match the filters.</td></tr>';
$$('#recentReqRows .req-row').forEach(tr=>tr.onclick=()=>{PW.reqOpen=PW.reqOpen===tr.dataset.rid?null:tr.dataset.rid;renderRecent()})};
$('#reqStatus').onchange=()=>{PW.reqFilter.status=$('#reqStatus').value;renderRecent()};
$('#reqSSE').onchange=()=>{PW.reqFilter.sse=$('#reqSSE').checked;renderRecent()};
$('#reqQuery').addEventListener('input',()=>{PW.reqFilter.q=$('#reqQuery').value.trim();renderRecent()});

/* --- Models table: search, state filter, sort, latency bars, proof age, cooldown countdown --- */
renderModels=function(ds,h){ds=ds||snap.deployments||[];h=h||healthMap();const f=PW.modelFilter;const q=(f.q||'').toLowerCase();let rows=ds.filter(d=>{const x=h[d.id]||{status:'unknown'};if(f.status!=='all'&&(x.status||'unknown')!==f.status)return false;if(q){const hay=(d.id+' '+d.provider_id+' '+(d.provider_name||'')+' '+d.model+' '+((d.aliases||[]).join(' '))).toLowerCase();if(!hay.includes(q))return false}return true});
rows=rows.slice().sort((a,b)=>{const xa=h[a.id]||{},xb=h[b.id]||{};if(f.sort==='latency')return((xa.ewma_latency_ms||1e12)-(xb.ewma_latency_ms||1e12))*f.dir;if(f.sort==='failures')return((xb.consecutive_failures||0)-(xa.consecutive_failures||0))*f.dir;if(f.sort==='proof'){const pa=xa.last_success?Date.parse(xa.last_success):0,pb=xb.last_success?Date.parse(xb.last_success):0;return (pb-pa)*f.dir}return String(a.id).localeCompare(String(b.id))*f.dir});
const maxLat=Math.max(1,...rows.map(d=>(h[d.id]||{}).ewma_latency_ms||0));
const cnt=$('#mwCount');if(cnt)cnt.textContent=rows.length+' of '+ds.length+' deployments';
$('#modelRows').innerHTML=rows.map(d=>{const x=h[d.id]||{status:'unknown'};const proof=x.last_success?agoStr(x.last_success):'never';const pAge=x.last_success?(Date.now()-Date.parse(x.last_success))/1000:1e12;const pCls=!x.last_success?'muted':pAge<310?'ok':'stale';const cdLeft=x.cooldown_until&&Date.parse(x.cooldown_until)>Date.now()?Math.ceil((Date.parse(x.cooldown_until)-Date.now())/1000)+'s left':'';const bw=x.ewma_latency_ms?Math.min(100,x.ewma_latency_ms/maxLat*100):0;return `<tr><td title="${esc(x.last_error||'')}">${esc(d.id)}</td><td>${esc(d.provider_id)}</td><td>${esc(d.model)}</td><td><span class="status ${esc(x.status)}">${esc(x.status)}</span>${cdLeft?` <small style="color:var(--warn)">${cdLeft}</small>`:''}</td><td><div class="latcell"><span>${x.ewma_latency_ms?Math.round(x.ewma_latency_ms)+' ms':'—'}</span><i style="width:${bw.toFixed(1)}%"></i></div></td><td><span class="proof ${pCls}" title="last success: ${esc(x.last_success||'never')}">${proof}</span></td><td>${x.consecutive_failures||0}<small style="color:var(--muted)">/${x.failures||0}</small></td><td><button class="btn secondary row-act" data-act="test" data-provider="${esc(d.provider_id)}" data-model="${esc(d.model)}">Test</button></td><td><button class="btn danger-ghost row-act" data-act="disable" data-provider="${esc(d.provider_id)}" data-mid="${esc(d.id.slice(d.provider_id.length+1))}" data-model="${esc(d.model)}">Disable</button></td></tr>`}).join('')||'<tr><td colspan="9" style="color:var(--muted)">No deployments match.</td></tr>';
$$('.row-act').forEach(b=>b.onclick=()=>{if(b.dataset.act==='test')testSavedModel(b.dataset.provider,[b.dataset.model],b);else toggleSavedModel(b.dataset.provider,b.dataset.mid,false,b)})};
$('#mwQuery').addEventListener('input',()=>{PW.modelFilter.q=$('#mwQuery').value.trim();renderModels()});
$('#mwStatus').onchange=()=>{PW.modelFilter.status=$('#mwStatus').value;renderModels()};
$('#mwSort').onchange=()=>{PW.modelFilter.sort=$('#mwSort').value;renderModels()};

/* --- Provider cards: batch test all models --- */
const _pwRenderProviders=renderProviders;
renderProviders=function(h){_pwRenderProviders(h);$$('.provider-card .edit-provider').forEach(b=>{const card=b.closest('.provider-card');if(!card||card.querySelector('.test-all-provider'))return;const btn=document.createElement('button');btn.className='btn secondary test-all-provider';btn.textContent='Test all models';btn.style.marginLeft='6px';btn.onclick=async()=>{btn.disabled=true;btn.textContent='Testing…';try{const d=await api('/admin/api/provider-test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({provider_id:b.dataset.id})});const r=d.results||[];const pass=r.filter(x=>x.ok).length;toast(b.dataset.id+': '+pass+'/'+r.length+' models passed',pass<r.length)}catch(e){toast(e.message,true)}finally{btn.disabled=false;btn.textContent='Test all models'}};b.parentElement.appendChild(btn)})};

/* --- Route Preview: capability requirements + live E2E route test + copy curl --- */
function testCurlFor(model,anthropic){const ep=anthropic?'/v1/messages':'/v1/chat/completions';const body=`{"model":"${model}","max_tokens":16,"messages":[{"role":"user","content":"ping"}]}`;const auth=anthropic?'x-api-key: <access-key>':'authorization: Bearer <access-key>';return `curl -s -w "\\nHTTP %{http_code}\\n" ${baseOrigin()}${ep} -H 'content-type: application/json' -H '${auth}' -d '${body}'`}
function baseOrigin(){return location.origin}
$('#previewBtn').onclick=async()=>{const m=$('#previewModel').value.trim();if(!m){toast('Enter a model or alias to preview',true);return}const btn=$('#previewBtn');btn.disabled=true;try{const body={model:m,tools:$('#pvTools').checked,vision:$('#pvVision').checked,streaming:$('#pvStream').checked,reasoning:$('#pvReason').checked,session_key:$('#previewSession').checked?('preview-'+Math.floor(Date.now()/1000)):''};const d=await api('/admin/api/route-preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const out=$('#previewOut');out.style.display='block';const cs=d.candidates||[];const anthropic=cs[0]&&cs[0].provider_type==='anthropic_compatible';out.innerHTML=`<div class="preview-head"><strong>Route Preview: ${esc(d.model)}</strong><span class="hint">strategy ${esc(d.strategy)} · ${d.candidate_count} eligible candidate(s) · max attempts ${d.max_attempts} · fallback ${d.fallback_enabled?'on':'off'}${d.session_pinned?` · pinned: ${esc(d.session_pinned)}`:''}</span><div class="preview-actions"><button id="pvRunBtn" class="btn secondary" type="button">▶ Send real test request</button><button id="pvCurlBtn" class="btn secondary" type="button">Copy test curl</button><span id="pvTestOut" class="hint"></span></div></div>${(d.notes||[]).map(n=>`<p class="hint" style="color:var(--warn);margin:6px 0">${esc(n)}</p>`).join('')}<div class="preview-list">${cs.map((c,i)=>`<div class="preview-card ${i===0?'top':''}"><div class="preview-top"><span class="rank">#${i+1}</span><strong>${esc(c.deployment_id)}</strong><span class="status ${esc(c.health)}">${esc(c.health)}</span>${c.session_pinned?'<span class="live">PIN</span>':''}<span class="spacer"></span><span class="hint">score ${c.score} · tier ${c.priority} · w ${c.weight} · ${c.ewma_latency_ms} ms · pressure ${(c.capacity_pressure*100).toFixed(0)}%</span></div><ul class="preview-reasons">${(c.reasons||[]).map(r=>`<li>${esc(r)}</li>`).join('')}</ul></div>`).join('')||'<p class="hint">No eligible deployments.</p>'}</div>`;
const runBtn=$('#pvRunBtn'),curlBtn=$('#pvCurlBtn');if(runBtn)runBtn.onclick=async()=>{runBtn.disabled=true;const t0=$('#pvTestOut');if(t0)t0.textContent='sending…';const started=performance.now();try{const ep=anthropic?'/v1/messages':'/v1/chat/completions';const hdrs={'content-type':'application/json'};await loadKeys();const k=(keyState.keys||[]).find(x=>x.enabled);if(k){if(anthropic)hdrs['x-api-key']=k.key;else hdrs.authorization='Bearer '+k.key}const r=await window.fetch(ep,{method:'POST',headers:hdrs,body:JSON.stringify({model:m,max_tokens:16,messages:[{role:'user',content:'ping'}]})});const ms=Math.round(performance.now()-started);let snippet='';try{const txt=await r.text();snippet=txt.slice(0,180)}catch{}const dep=r.headers.get('x-gateway-deployment')||'?';if(t0)t0.innerHTML=`<span class="status ${r.status<300?'healthy':r.status<500?'degraded':'cooldown'}">${r.status}</span> via ${esc(dep)} · ${ms} ms <code>${esc(snippet)}…</code>`;if(t0&&r.status>=300)t0.style.color='var(--warn)'}catch(e){if(t0)t0.textContent=e.message}finally{runBtn.disabled=false}};
if(curlBtn)curlBtn.onclick=async()=>{try{await navigator.clipboard.writeText(testCurlFor(m,anthropic));toast('Test curl copied — paste an access key and run')}catch{toast('Clipboard unavailable',true)}}}catch(e){toast(e.message,true)}finally{btn.disabled=false}};

/* --- CLI tab: real snippets from live origin + first enabled key --- */
async function renderCLI(){const grid=$('#cliGrid');if(!grid)return;await loadKeys();const base=baseOrigin();const k=(keyState.keys||[]).find(x=>x.enabled);const key=k?k.key:'<access-key-from-Access-Keys-tab>';const blocks=[['Claude Code (Anthropic ingress)','Point Claude Code at the local gateway; routing is transparent.',`export ANTHROPIC_BASE_URL=${base}\nexport ANTHROPIC_AUTH_TOKEN=${key}\n# optional safety placeholder if the tool demands a key format:\n# export ANTHROPIC_API_KEY=${key}`],['OpenAI-compatible tools','Any tool speaking Chat Completions rides the same pool.',`export OPENAI_BASE_URL=${base}/v1\nexport OPENAI_API_KEY=${key}`],['Anthropic curl smoke test','Proves the full route: auth → alias resolution → deployment → response.',`curl -s -w "\\nHTTP %{http_code}\\n" ${base}/v1/messages \\\n  -H 'x-api-key: ${key}' -H 'content-type: application/json' \\\n  -d '{"model":"auto","max_tokens":32,"messages":[{"role":"user","content":"hello"}]}'`],['Route preview (admin API)','Explains the routing decision without sending traffic.',`curl -s ${base}/admin/api/route-preview \\\n  -H 'x-admin-key: <admin-key>' -H 'content-type: application/json' \\\n  -d '{"model":"auto","tools":true}'`],['Readiness & metrics','Health for load balancers; Prometheus metrics for dashboards.',`curl -s ${base}/readyz\ncurl -s ${base}/metrics | head -40`]];grid.innerHTML=blocks.map((b,i)=>`<div class="cli-card"><h3>${esc(b[0])}</h3><p>${esc(b[1])}</p><pre><code>${esc(b[2])}</code></pre><button class="btn secondary cli-copy" data-i="${i}">Copy</button></div>`).join('');$$('.cli-copy').forEach(x=>x.onclick=async()=>{try{await navigator.clipboard.writeText(blocks[+x.dataset.i][2]);toast('Snippet copied')}catch{toast('Clipboard unavailable',true)}})}
$$('nav button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.tab==='cli')renderCLI()}));

/* --- Settings: config copy / download --- */
$('#copyConfigBtn').onclick=async()=>{try{await navigator.clipboard.writeText($('#settingsJson').textContent);toast('Config JSON copied')}catch{toast('Clipboard unavailable — use Download',true)}};
$('#downloadConfigBtn').onclick=()=>{const blob=new Blob([$('#settingsJson').textContent],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='nexaroute-config.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),500)};

/* --- Header: pause / refresh-now --- */
$('#pauseBtn').onclick=()=>{PW.paused=!PW.paused;$('#pauseBtn').textContent=PW.paused?'▶ Resume':'⏸ Pause';if(!PW.paused)refresh();else $('#apiState').textContent='● paused'};
$('#refreshNowBtn').onclick=()=>refresh();

/* --- chart window selector --- */
$$('.chart-win').forEach(b=>b.onclick=()=>{$$('.chart-win').forEach(x=>x.classList.remove('active'));b.classList.add('active');PW.win=+b.dataset.win;renderTrafficChart()});

refresh();
